 {page==='storage-locations'&&<><div className="search standalone"><Search size={17}/><input aria-label="Search locations" placeholder="Search storage locations…" value={search} onChange={e=>setSearch(e.target.value)}/></div><div className="locations-grid">{locations.filter(l=>(l.name+' '+l.description).toLowerCase().includes(search.toLowerCase())).map(l=>{const locationBalances=balances.filter(b=>b.location_id===l.id);const list=items.filter(i=>locationBalances.some(b=>b.item_id===i.id&&b.quantity>0)||i.location_id===l.id);return <section className="panel location-card" key={l.id}><div className="location-icon"><MapPin size={24}/></div><h2>{l.name}</h2><p>{l.description||'Office storage location'}</p><div className="location-stats"><div><strong>{list.length}</strong><small>Items stored</small></div><div><strong>{locationBalances.filter(b=>b.quantity>0).length}</strong><small>Items in stock</small></div></div><button className="panel-footer-button" onClick={()=>{go('inventory');setLocationFilter(l.id);setLifecycleFilter('all');setStockFilter('All statuses');setCategory('All categories')}}>Browse items<ArrowRight size={16}/></button></section>})}</div>{!locations.filter(l=>(l.name+' '+l.description).toLowerCase().includes(search.toLowerCase())).length&&<div className="panel empty">{locations.length?'No locations match your search.':admin?'Add a storage location to organize your inventory.':'Your admin can add the first storage location.'}</div>}</>}
